// Benchmark boilerplate generated by Benchmark

import Benchmark
import SolidRaster
import SolidRasterBenchmarkSupport

let benchmarks: @Sendable () -> Void = {
  let pathWidth = RasterBenchmarkFixtures.pathSurfaceWidth
  let pathHeight = RasterBenchmarkFixtures.pathSurfaceHeight
  let surfacePath = try! RasterBenchmarkFixtures.surfacePath()
  let cubicPath = try! RasterBenchmarkFixtures.cubicPath()
  let deepClip = try! RasterBenchmarkFixtures.deepClip()
  let sourceImage = try! RasterBenchmarkFixtures.largeImage()

  let metrics: [BenchmarkMetric] = [
    .wallClock,
    .cpuTotal,
    .throughput,
    .mallocCountTotal,
    .peakMemoryResidentDelta,
  ]
  let configuration = Benchmark.Configuration(
    metrics: metrics,
    warmupIterations: 3,
    scalingFactor: .one,
    maxDuration: .seconds(3),
    maxIterations: 100
  )

  Benchmark("Flat Fill", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var canvas = try! RasterCanvas(width: pathWidth, height: pathHeight)
      try! canvas.fill(surfacePath, rule: .winding, paint: .solid(.black))
      blackHole(try! canvas.finish(pixelFormat: .rgba8UnormPremultiplied))
    }
  }

  Benchmark("1,000 Cubic Fill", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var canvas = try! RasterCanvas(width: pathWidth, height: pathHeight)
      try! canvas.fill(cubicPath, rule: .winding, paint: .solid(.black))
      blackHole(try! canvas.finish(pixelFormat: .rgba8UnormPremultiplied))
    }
  }

  Benchmark("Dashed Stroke", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var canvas = try! RasterCanvas(width: pathWidth, height: pathHeight)
      try! canvas.stroke(
        cubicPath,
        style: RasterBenchmarkFixtures.dashedStrokeStyle,
        paint: .solid(RasterColor(red: 0.1, green: 0.4, blue: 0.8))
      )
      blackHole(try! canvas.finish(pixelFormat: .rgba8UnormPremultiplied))
    }
  }

  Benchmark("Deep Clip Fill", configuration: configuration) { benchmark in
    benchmark.startMeasurement()
    for _ in benchmark.scaledIterations {
      var canvas = try! RasterCanvas(width: pathWidth, height: pathHeight)
      try! canvas.setClip(deepClip)
      try! canvas.fill(surfacePath, rule: .winding, paint: .solid(.black))
      blackHole(try! canvas.finish(pixelFormat: .rgba8UnormPremultiplied))
    }
  }

  for interpolation in [RasterInterpolation.nearest, .linear] {
    let name = interpolation == .nearest ? "8 MP Nearest Image" : "8 MP Bilinear Image"
    Benchmark(name, configuration: configuration) { benchmark in
      benchmark.startMeasurement()
      for _ in benchmark.scaledIterations {
        var canvas = try! RasterCanvas(
          width: RasterBenchmarkFixtures.imageWidth,
          height: RasterBenchmarkFixtures.imageHeight
        )
        try! canvas.draw(sourceImage, transform: .identity, interpolation: interpolation)
        blackHole(try! canvas.finish(pixelFormat: .rgba8UnormPremultiplied))
      }
    }
  }
}
